package com.bplus.share;
import org.json.*;import java.io.*;import java.net.*;import android.net.Uri;import java.util.*;
/** Live local host groups, separate from legacy file recipient lists. */
public final class LocalGroups{
 public static String self(){return Store.get("deviceId","");}static String newId(){return UUID.randomUUID().toString().replace("-","");}
 public static synchronized JSONArray all(){try{return new JSONArray(Store.get("liveGroups","[]"));}catch(Exception e){return new JSONArray();}}
 public static synchronized JSONObject get(String id){JSONArray a=all();for(int i=0;i<a.length();i++){JSONObject g=a.optJSONObject(i);if(g!=null&&g.optString("id").equals(id))return g;}return null;}
 public static synchronized void put(JSONObject g)throws Exception{JSONArray a=all();boolean seen=false;for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("id").equals(g.getString("id"))){a.put(i,g);seen=true;}if(!seen)a.put(g);Store.durable("liveGroups",a.toString());TransferService.changed("");}
 public static JSONObject create(String name)throws Exception{if(name==null||name.trim().isEmpty()||name.length()>60)throw new IOException("Invalid group name");name=name.trim();JSONObject g=new JSONObject();g.put("id",newId());g.put("name",name);g.put("host",self());g.put("joined",true);g.put("members",new JSONArray());put(g);return g;}
 public static JSONObject call(String ip,String route,JSONObject b)throws Exception{return Nearby.call(ip,"/group/"+route,b);}
 public static void invite(String gid,JSONObject peer)throws Exception{JSONObject g=get(gid);if(g==null||!g.optString("host").equals(self()))throw new IOException("Host required");String key=newId();JSONObject m=new JSONObject();m.put("id",peer.getString("id"));m.put("name",peer.optString("name"));m.put("ip",peer.getString("ip"));m.put("key",key);m.put("joined",false);synchronized(LocalGroups.class){g=get(gid);JSONArray members=g.getJSONArray("members");boolean exists=false;for(int i=0;i<members.length();i++)if(members.getJSONObject(i).getString("id").equals(m.getString("id"))){m=members.getJSONObject(i);key=m.getString("key");exists=true;break;}if(!exists)members.put(m);put(g);}JSONObject b=new JSONObject();b.put("group",gid);b.put("name",g.getString("name"));b.put("host",self());b.put("hostName",Profile.local().optString("name"));b.put("key",key);b.put("token",Store.token());call(peer.getString("ip"),"invite",b);}
 public static void join(String gid)throws Exception{JSONObject g=get(gid);JSONObject b=auth(g);b.put("member",self());call(g.getString("ip"),"join",b);g.put("joined",true);put(g);}
 static JSONObject auth(JSONObject g)throws Exception{return new JSONObject().put("group",g.getString("id")).put("key",g.getString("key"));}
 static JSONObject member(JSONObject g,String key,String ip)throws Exception{JSONArray a=g.getJSONArray("members");for(int i=0;i<a.length();i++){JSONObject m=a.getJSONObject(i);if(m.optString("key").equals(key)&&m.optString("ip").equals(ip))return m;}throw new IOException("Not a member");}
 static boolean isHost(JSONObject g){return g!=null&&g.optString("host").equals(self());}
 static void verifyHost(JSONObject g,JSONObject b,String ip)throws Exception{if(!g.optBoolean("joined")||!g.optString("ip").equals(ip)||!g.optString("key").equals(b.optString("key")))throw new IOException("Host unavailable");}

 static JSONObject findMessage(String gid,String id){JSONArray t=Store.thread("live_"+gid);for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&id.equals(m.optString("id")))return m;}return null;}
 public static boolean canDelete(JSONObject g,JSONObject m){return g!=null&&m!=null&&!g.optBoolean("deleted")&&(isHost(g)||self().equals(m.optString("sender")));}
 static boolean dead(String gid,String id){return Store.get("groupDeleted_"+gid,"0").equals("1")||Store.get("groupTomb_"+gid+"_"+id,"0").equals("1");}
 static void tomb(String gid,String id,String actor)throws Exception{if(!id.matches("[a-zA-Z0-9]{32}"))throw new IOException("Invalid file ID");JSONArray t=Store.thread("live_"+gid);boolean found=false;for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&id.equals(m.optString("id"))){if(!m.optString("kind").equals("file")&&!m.optString("kind").equals("deleted"))throw new IOException("File delete only");t.put(i,new JSONObject().put("id",id).put("kind","deleted").put("actor",actor).put("ts",m.optLong("ts")).put("state","deleted"));found=true;}}if(!found)t.put(new JSONObject().put("id",id).put("kind","deleted").put("actor",actor).put("ts",System.currentTimeMillis()).put("state","deleted"));Store.durable("groupTomb_"+gid+"_"+id,"1");Store.saveThread("live_"+gid,t);TransferService.changed("");}
 static void removeGroup(JSONObject g)throws Exception{Store.durable("groupDeleted_"+g.getString("id"),"1");g.put("deleted",true);put(g);Store.saveThread("live_"+g.getString("id"),new JSONArray());}
 public static synchronized void deleteFile(String gid,String id)throws Exception{JSONObject g=get(gid),m=findMessage(gid,id);if(!canDelete(g,m)||!m.optString("kind").equals("file"))throw new IOException("Only creator or uploader can delete this shared file");if(isHost(g)){tomb(gid,id,Profile.local().optString("name"));queueControl(g,"delete-deliver",id,Profile.local().optString("name"));}else{JSONObject result=call(g.getString("ip"),"delete",auth(g).put("id",id));tomb(gid,id,result.optString("actor",Profile.local().optString("name")));}}
 public static synchronized void deleteGroup(String gid)throws Exception{JSONObject g=get(gid);if(g==null||!isHost(g))throw new IOException("Only creator can delete group");queueControl(g,"group-deleted","",self());removeGroup(g);}
 static synchronized void queueControl(JSONObject g,String route,String id,String actor)throws Exception{JSONArray q=new JSONArray(Store.get("groupControlQueue","[]")),members=g.optJSONArray("members");if(members!=null)for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m==null||!m.optBoolean("joined"))continue;JSONObject b=new JSONObject().put("group",g.getString("id")).put("key",m.getString("key")).put("id",id).put("actor",actor);q.put(new JSONObject().put("ip",m.getString("ip")).put("route",route).put("body",b));}Store.durable("groupControlQueue",q.toString());sending.execute(LocalGroups::flushControl);}
 public static synchronized void flushControl(){JSONArray q;try{q=new JSONArray(Store.get("groupControlQueue","[]"));}catch(Exception e){return;}JSONArray left=new JSONArray();for(int i=0;i<q.length();i++){JSONObject op=q.optJSONObject(i);try{if(op.optLong("next")>System.currentTimeMillis()){left.put(op);continue;}call(op.getString("ip"),op.getString("route"),op.getJSONObject("body"));}catch(Exception e){try{int tries=op.optInt("tries")+1;op.put("tries",tries).put("error","pending - offline or older app").put("next",System.currentTimeMillis()+Math.min(300000,30000L*(1L<<Math.min(tries,4))));}catch(Exception ignored){}left.put(op);}}try{Store.durable("groupControlQueue",left.toString());}catch(Exception ignored){}}
 public static int pending(String gid){try{JSONArray q=new JSONArray(Store.get("groupControlQueue","[]"));int n=0;for(int i=0;i<q.length();i++)if(gid.equals(q.getJSONObject(i).getJSONObject("body").optString("group")))n++;return n;}catch(Exception e){return 0;}}
 public static boolean memberPending(String gid,String member){JSONObject g=get(gid);if(g==null)return false;JSONArray members=g.optJSONArray("members");String ip="";if(members!=null)for(int i=0;i<members.length();i++){JSONObject m=members.optJSONObject(i);if(m!=null&&member.equals(m.optString("id")))ip=m.optString("ip");}try{JSONArray q=new JSONArray(Store.get("groupControlQueue","[]"));for(int i=0;i<q.length();i++){JSONObject op=q.getJSONObject(i);if(gid.equals(op.getJSONObject("body").optString("group"))&&ip.equals(op.optString("ip")))return true;}}catch(Exception ignored){}return false;}
 private static boolean controlStarted;public static synchronized void start(){if(controlStarted)return;controlStarted=true;java.util.concurrent.Executors.newSingleThreadScheduledExecutor().scheduleWithFixedDelay(()->{flushControl();flushFiles();},3,30,java.util.concurrent.TimeUnit.SECONDS);}
 public static void retryFile(String gid,JSONObject old)throws Exception{JSONObject g=get(gid);if(g==null||g.optBoolean("deleted")||dead(gid,old.optString("id")))throw new IOException("File/group deleted");if(!isHost(g)&&!self().equals(old.optString("sender")))throw new IOException("Only uploader can resend");if(!FileConsent.ask(g.optString("name"),old.optString("name"),old.optLong("size")))throw new IOException("Resend canceled");try{status(gid,old.getString("id"),"sending");if(isHost(g))broadcast(g,old);else{upload(g.getString("ip"),"file",auth(g),old,Uri.parse(old.getString("uri")));status(gid,old.getString("id"),"received by host");}}catch(Exception e){status(gid,old.optString("id"),"failed: "+e.getMessage());throw e;}}
 static synchronized void contact(JSONObject g,JSONObject m){final String ip=m.optString("ip");try{JSONArray q=new JSONArray(Store.get("groupFileQueue","[]"));for(int i=0;i<q.length();i++)if(ip.equals(q.getJSONObject(i).optString("ip")))q.getJSONObject(i).put("next",0);Store.durable("groupFileQueue",q.toString());JSONArray c=new JSONArray(Store.get("groupControlQueue","[]"));for(int i=0;i<c.length();i++)if(ip.equals(c.getJSONObject(i).optString("ip")))c.getJSONObject(i).put("next",0);Store.durable("groupControlQueue",c.toString());}catch(Exception ignored){}sending.execute(()->{flushControl();flushFiles();});}
 static synchronized void filePending(JSONObject g,JSONObject member,JSONObject message,boolean failed){try{JSONArray q=new JSONArray(Store.get("groupFileQueue","[]")),out=new JSONArray();for(int i=0;i<q.length();i++){JSONObject old=q.getJSONObject(i);if(!(old.optString("group").equals(g.optString("id"))&&old.optString("member").equals(member.optString("id"))&&old.optString("id").equals(message.optString("id"))))out.put(old);}if(failed)out.put(new JSONObject().put("group",g.getString("id")).put("member",member.getString("id")).put("ip",member.getString("ip")).put("id",message.getString("id")));Store.durable("groupFileQueue",out.toString());}catch(Exception ignored){}}
 static synchronized void flushFiles(){try{JSONArray q=new JSONArray(Store.get("groupFileQueue","[]")),left=new JSONArray();for(int i=0;i<q.length();i++){JSONObject op=q.getJSONObject(i);if(dead(op.optString("group"),op.optString("id")))continue;JSONObject g=get(op.getString("group")),msg=findMessage(op.getString("group"),op.getString("id"));if(g==null||msg==null||!msg.optString("kind").equals("file"))continue;if(op.optLong("next")>System.currentTimeMillis()){left.put(op);continue;}JSONObject member=null;JSONArray members=g.optJSONArray("members");if(members!=null)for(int j=0;j<members.length();j++)if(op.getString("member").equals(members.getJSONObject(j).optString("id")))member=members.getJSONObject(j);if(member==null)continue;try{JSONObject b=new JSONObject().put("group",g.getString("id")).put("key",member.getString("key"));upload(member.getString("ip"),"file-deliver",b,msg,Uri.parse(msg.getString("uri")));}catch(Exception e){int tries=op.optInt("tries")+1;op.put("tries",tries).put("error","pending - offline or older app").put("next",System.currentTimeMillis()+Math.min(300000,30000L*(1L<<Math.min(tries,4))));left.put(op);}}Store.durable("groupFileQueue",left.toString());for(int i=0;i<q.length();i++){JSONObject op=q.getJSONObject(i);int count=0;for(int j=0;j<left.length();j++)if(op.optString("group").equals(left.getJSONObject(j).optString("group"))&&op.optString("id").equals(left.getJSONObject(j).optString("id")))count++;status(op.optString("group"),op.optString("id"),count>0?count+" failed - pending retry":"delivered");}}catch(Exception ignored){}}
 public static synchronized JSONObject handle(String route,JSONObject b,String ip)throws Exception{
  if(route.equals("invite")){JSONObject host=Store.peerById(b.getString("host"));if(host==null||!host.optString("ip").equals(ip)||!host.optString("token").equals(b.optString("token")))throw new IOException("Pair first");String id=b.getString("group"),key=b.getString("key"),name=b.getString("name");if(!id.matches("[a-zA-Z0-9]{32}")||!key.matches("[a-zA-Z0-9]{32}")||name.length()>60)throw new IOException("Invalid invite");if(get(id)!=null)return new JSONObject().put("status","exists");JSONObject g=new JSONObject();g.put("id",id);g.put("name",name);g.put("host",host.getString("id"));g.put("hostName",host.optString("name"));g.put("ip",ip);g.put("key",key);g.put("joined",false);put(g);return new JSONObject().put("status","invited");}
  JSONObject g=get(b.getString("group"));if(g==null)throw new IOException("Unknown group");
  if(route.equals("group-deleted")){verifyHost(g,b,ip);removeGroup(g);new android.os.Handler(android.os.Looper.getMainLooper()).post(()->android.widget.Toast.makeText(App.ctx(),R.string.group_deleted_host,1).show());return new JSONObject().put("status","deleted");}
  if(route.equals("delete-deliver")){verifyHost(g,b,ip);tomb(g.getString("id"),b.getString("id"),b.optString("actor"));return new JSONObject().put("status","deleted");}
  if(g.optBoolean("deleted"))throw new IOException("Group deleted");
  if(route.equals("delete")){if(!isHost(g))throw new IOException("Host required");JSONObject member=member(g,b.getString("key"),ip);if(!member.optBoolean("joined"))throw new IOException("Join first");String id=b.getString("id");contact(g,member);if(!dead(g.getString("id"),id)){JSONObject msg=findMessage(g.getString("id"),id);if(msg==null||!msg.optString("kind").equals("file")||!member.getString("id").equals(msg.optString("sender")))throw new IOException("Only uploader can delete");tomb(g.getString("id"),id,member.optString("name"));queueControl(g,"delete-deliver",id,member.optString("name"));}JSONObject deleted=findMessage(g.getString("id"),id);return new JSONObject().put("status","deleted").put("actor",deleted==null?member.optString("name"):deleted.optString("actor",member.optString("name")));}
  if(route.equals("join")){if(!isHost(g))throw new IOException();JSONObject m=member(g,b.getString("key"),ip);if(!m.optString("id").equals(b.getString("member")))throw new IOException();m.put("joined",true);put(g);contact(g,m);return new JSONObject().put("status","joined");}
  if(route.equals("message")){if(!isHost(g))throw new IOException();JSONObject m=member(g,b.getString("key"),ip);if(!m.optBoolean("joined"))throw new IOException("Join first");contact(g,m);JSONObject msg=cleanMessage(b.getJSONObject("message"));msg.put("sender",m.getString("id"));msg.put("senderName",m.optString("name"));boolean fresh=add(g.getString("id"),msg);if(fresh)queueBroadcast(g,msg);return new JSONObject().put("status","received by host");}
  if(route.equals("deliver")){verifyHost(g,b,ip);JSONObject msg=cleanMessage(b.getJSONObject("message"));add(g.getString("id"),msg);return new JSONObject().put("status","received");}
  throw new IOException("Unknown group route");
 }
 static JSONObject cleanMessage(JSONObject in)throws Exception{String id=in.getString("id"),body=in.optString("body");if(!id.matches("[a-zA-Z0-9]{32}")||body.length()>8000)throw new IOException("Invalid message");JSONObject m=new JSONObject();m.put("id",id);m.put("kind","text");m.put("body",body);m.put("sender",in.optString("sender").substring(0,Math.min(80,in.optString("sender").length())));m.put("senderName",in.optString("senderName").substring(0,Math.min(80,in.optString("senderName").length())));m.put("ts",System.currentTimeMillis());return m;}
 static synchronized boolean add(String gid,JSONObject msg)throws Exception{if(dead(gid,msg.getString("id")))return false;JSONArray t=Store.thread("live_"+gid);for(int i=0;i<t.length();i++)if(t.getJSONObject(i).optString("id").equals(msg.getString("id")))return false;if(!msg.has("ts"))msg.put("ts",System.currentTimeMillis());msg.put("me",msg.optString("sender").equals(self()));msg.put("state","received");Store.addMsg("live_"+gid,msg);TransferService.changed("");if(!msg.optBoolean("me"))Alerts.message(msg.optString("senderName"),msg);return true;}
 static final java.util.concurrent.ExecutorService sending=java.util.concurrent.Executors.newSingleThreadExecutor();
 static void queueBroadcast(JSONObject g,JSONObject m){sending.execute(()->broadcast(g,m));}
 static synchronized void broadcast(JSONObject g,JSONObject m){JSONArray members=g.optJSONArray("members");if(members==null)return;if(dead(g.optString("id"),m.optString("id")))return;int good=0,bad=0;for(int i=0;i<members.length();i++){JSONObject p=members.optJSONObject(i);if(p==null||!p.optBoolean("joined")||p.optString("id").equals(m.optString("sender")))continue;try{if(m.optString("kind").equals("file"))filePending(g,p,m,true);JSONObject b=new JSONObject().put("group",g.getString("id")).put("key",p.getString("key"));if(m.optString("kind").equals("file"))upload(p.getString("ip"),"file-deliver",b,m,Uri.parse(m.getString("uri")));else{JSONObject portable=new JSONObject(m.toString());portable.remove("uri");b.put("message",portable);call(p.getString("ip"),"deliver",b);}good++;if(m.optString("kind").equals("file"))filePending(g,p,m,false);}catch(Exception e){bad++;if(m.optString("kind").equals("file"))filePending(g,p,m,true);}}status(g.optString("id"),m.optString("id"),good+" delivered / "+bad+" failed");}
 static synchronized void status(String gid,String id,String state){JSONArray t=Store.thread("live_"+gid);for(int i=0;i<t.length();i++){JSONObject m=t.optJSONObject(i);if(m!=null&&id.equals(m.optString("id"))&&!m.optString("kind").equals("deleted"))try{m.put("state",state);}catch(Exception ignored){}}Store.saveThread("live_"+gid,t);}
 public static void sendText(String gid,String body)throws Exception{if(body.isEmpty()||body.length()>8000)throw new IOException("Message too long");JSONObject g=get(gid);if(g==null||g.optBoolean("deleted")||!g.optBoolean("joined"))throw new IOException("Join first");JSONObject m=new JSONObject().put("id",newId()).put("kind","text").put("body",body).put("sender",self()).put("senderName",Profile.local().optString("name"));add(gid,m);try{if(isHost(g))broadcast(g,m);else{JSONObject b=auth(g).put("message",m);call(g.getString("ip"),"message",b);status(gid,m.getString("id"),"received by host");}}catch(Exception e){status(gid,m.getString("id"),"failed: "+e.getClass().getSimpleName());throw e;}}
 public static void sendFile(String gid,Uri uri,String name,long size)throws Exception{sendOriginal(gid,uri,name,size,false);}
 static void sendRecordedVoice(String gid,Uri uri,String name,long size)throws Exception{sendOriginal(gid,uri,name,size,true);}
 private static void sendOriginal(String gid,Uri uri,String name,long size,boolean micRelease)throws Exception{JSONObject target=get(gid);if(target==null||(!micRelease&&!FileConsent.ask(target.optString("name"),name,size)))throw new IOException("File send canceled");if(name==null||name.length()>240||size<0||size>=Integer.MAX_VALUE)throw new IOException("File size unsupported");JSONObject g=get(gid);if(g==null||g.optBoolean("deleted")||!g.optBoolean("joined"))throw new IOException("Join first");JSONObject m=new JSONObject().put("id",newId()).put("kind","file").put("name",name).put("size",size).put("uri",uri.toString()).put("mime",Save.mime(name)).put("sender",self()).put("senderName",Profile.local().optString("name"));add(gid,m);try{if(isHost(g))broadcast(g,m);else{upload(g.getString("ip"),"file",auth(g),m,uri);status(gid,m.getString("id"),"received by host");}}catch(Exception e){status(gid,m.getString("id"),"failed: "+e.getClass().getSimpleName());throw e;}}
 static void upload(String ip,String route,JSONObject b,JSONObject m,Uri uri)throws Exception{if(dead(b.getString("group"),m.getString("id")))throw new IOException("File deleted");String url="http://"+ip+":"+Store.PORT+"/group/"+route+"?group="+b.getString("group")+"&key="+b.getString("key")+"&id="+m.getString("id")+"&name="+URLEncoder.encode(m.getString("name"),"UTF-8")+"&sender="+m.optString("sender")+"&senderName="+URLEncoder.encode(m.optString("senderName"),"UTF-8");HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setDoOutput(true);c.setFixedLengthStreamingMode(m.getLong("size"));try{try(InputStream in=App.ctx().getContentResolver().openInputStream(uri);OutputStream out=c.getOutputStream()){if(in==null)throw new IOException("Missing file");byte[] buf=new byte[65536];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());}finally{c.disconnect();}}
 public static synchronized void receiveFile(String route,Map<String,String> q,String ip,InputStream in,int len)throws Exception{JSONObject g=get(q.get("group"));if(g==null||g.optBoolean("deleted")||len<0)throw new IOException();JSONObject b=new JSONObject().put("key",q.get("key"));String sender,senderName;if(route.equals("file")){if(!isHost(g))throw new IOException();JSONObject m=member(g,q.get("key"),ip);if(!m.optBoolean("joined"))throw new IOException();contact(g,m);sender=m.getString("id");senderName=m.optString("name");}else{verifyHost(g,b,ip);sender=q.get("sender");senderName=URLDecoder.decode(q.getOrDefault("senderName",""),"UTF-8");}String id=q.get("id");if(id==null||!id.matches("[a-zA-Z0-9]{32}"))throw new IOException();if(dead(g.getString("id"),id))throw new IOException("File deleted");String name=URLDecoder.decode(q.getOrDefault("name","file"),"UTF-8");if(name.length()>240)throw new IOException();JSONArray existing=Store.thread("live_"+g.getString("id"));for(int i=0;i<existing.length();i++)if(existing.getJSONObject(i).optString("id").equals(id)){byte[] skip=new byte[65536];int left=len,n;while(left>0){n=in.read(skip,0,Math.min(skip.length,left));if(n<0)throw new IOException("Incomplete duplicate");left-=n;}JSONObject prior=existing.getJSONObject(i);if(!sender.equals(prior.optString("sender")))throw new IOException("File ID owned by another uploader");if(isHost(g))queueBroadcast(g,prior);return;}Save.Target target=Save.create(App.ctx(),name);try{byte[] buf=new byte[65536];int remaining=len,n;while(remaining>0){n=in.read(buf,0,Math.min(buf.length,remaining));if(n<0)throw new IOException("Incomplete file");target.out.write(buf,0,n);remaining-=n;}target.complete();JSONObject m=new JSONObject().put("id",id).put("kind","file").put("name",name).put("size",len).put("uri",target.uri.toString()).put("mime",Save.mime(name)).put("sender",sender).put("senderName",senderName).put("ts",System.currentTimeMillis());add(g.getString("id"),m);if(isHost(g))queueBroadcast(g,m);}catch(Exception e){target.abort();throw e;}}
}
